class QrResultScreen extends StatefulWidget { const QrResultScreen({required this.values,super.key});final List<String> values;@override State<QrResultScreen> createState()=>_QrResultScreenState(); }
class _QrResultScreenState extends State<QrResultScreen>{int selected=0;@override Widget build(BuildContext context){final s=S.of(context),value=widget.values[selected],decision=LinkPolicy.inspect(value);return Scaffold(appBar:AppBar(title:Text(s.t('QR result','ผลคิวอาร์'))),body:ListView(padding:const EdgeInsets.all(20),children:[if(widget.values.length>1)...[Text(s.t('${widget.values.length} codes detected. Select one:','พบ ${widget.values.length} โค้ด เลือกหนึ่งรายการ:'),style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:8),DropdownButtonFormField<int>(initialValue:selected,items:List.generate(widget.values.length,(i)=>DropdownMenuItem(value:i,child:Text('${i+1}. ${widget.values[i]}',maxLines:1,overflow:TextOverflow.ellipsis))),onChanged:(i)=>setState(()=>selected=i!)),const SizedBox(height:24)],if(decision.hostname!=null)...[Text(s.t('Destination hostname','ชื่อโฮสต์ปลายทาง')),SelectableText(decision.hostname!,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:16)],Text(decision.canOpen?s.t('Complete content','เนื้อหาทั้งหมด'):s.t('Text content','เนื้อหาข้อความ'),style:Theme.of(context).textTheme.labelLarge),const SizedBox(height:6),SelectableText(value),if(!decision.canOpen)...[const SizedBox(height:12),Text(s.t('This content cannot be opened, but you can copy or share it.','ไม่สามารถเปิดเนื้อหานี้ได้ แต่คุณคัดลอกหรือแชร์ได้'))],const SizedBox(height:28),Wrap(spacing:12,runSpacing:12,children:[if(decision.canOpen)FilledButton.icon(onPressed:()async{final ok=await launchUrl(decision.uri!,mode:LaunchMode.externalApplication);if(!ok&&context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.t('No installed app can open this destination.','ไม่มีแอปที่เปิดปลายทางนี้ได้'))));},icon:const Icon(Icons.open_in_new),label:Text(s.t('Open','เปิด'))),OutlinedButton.icon(onPressed:(){Clipboard.setData(ClipboardData(text:value));ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s.t('Copied','คัดลอกแล้ว'))));},icon:const Icon(Icons.copy),label:Text(s.t('Copy','คัดลอก'))),OutlinedButton.icon(onPressed:()=>SharePlus.instance.share(ShareParams(text:value)),icon:const Icon(Icons.share),label:Text(s.t('Share','แชร์')))])]));}}
